// Translate the display strings generated by skillBuildSummary, not the build.
export function localizeSkillSummary(summary,tr){
 const patterns=[
  [/^Soldier damage \+(\d+)$/,'Soldier damage +{value}'],[/^Tower damage \+(\d+)%$/,'Tower damage +{value}%'],[/^Supplies per kill \+(\d+)$/,'Supplies per kill +{value}'],[/^Bunker maximum health \+(\d+)$/,'Bunker maximum health +{value}'],[/^Movement speed \+(\d+)$/,'Movement speed +{value}'],[/^Soldier range \+(\d+)$/,'Soldier range +{value}'],[/^Soldier firing interval (\d+)% of base$/,'Soldier firing interval {value}% of base'],[/^Tower firing interval (\d+)% of base$/,'Tower firing interval {value}% of base'],[/^Starting supplies \+(\d+)$/,'Starting supplies +{value}'],[/^Ability cooldown reduction (\d+)s \(minimum 10s\)$/,'Ability cooldown reduction {value}s (minimum 10s)']
 ];
 const values=summary.values.map(text=>{for(const [pattern,key] of patterns){const m=text.match(pattern);if(m)return tr(key,{value:m[1]});}return tr(text);});
 const combos=summary.combos.map(text=>{const m=text.match(/^(.*) (\d+\/3)$/);return m?`${tr(m[1])} ${m[2]}`:tr(text);});
 return {active:tr(summary.points===1?'ACTIVE: {name} · {count} unspent point':'ACTIVE: {name} · {count} unspent points',{name:tr(summary.active),count:summary.points}),values,combos:combos.length?tr('Combos: {items}',{items:combos.join(' · ')}):tr('No hybrid combos unlocked.'),caps:summary.caps.length?tr('Capstones: {items}',{items:summary.caps.map(x=>tr(x)).join(' · ')}):tr('No capstones unlocked.')};
}
